import itertools
from itertools import combinations
import z3

n = 16

solver = z3.Solver()

# Edge variables
edge = {}
for i in range(n):
    for j in range(i+1, n):
        edge[(i,j)] = z3.Bool(f"e_{i}_{j}")

# Color variables
color = [z3.Int(f"c_{i}") for i in range(n)]
for i in range(n):
    solver.add(z3.And(color[i] >= 0, color[i] <= 2))

# At least 23 edges
solver.add(z3.Sum([z3.If(edge[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)]) >= 23)

# 3-colorable: edges only between different colors
for i in range(n):
    for j in range(i+1, n):
        solver.add(z3.Implies(edge[(i,j)], color[i] != color[j]))

# Girth >= 7: no cycles of length 3, 4, 5, or 6
# For each possible cycle of length k (3 <= k <= 6), at least one edge must be missing

def generate_cycles(k):
    cycles = []
    for combo in combinations(range(n), k):
        # For each permutation, but canonicalize to avoid duplicates
        for perm in itertools.permutations(combo):
            # Canonical: smallest vertex first, and second < last
            if perm[0] != min(combo):
                continue
            if perm[1] > perm[-1]:
                continue
            cycles.append(perm)
    return cycles

print("Generating cycle constraints...")
for k in [3, 4, 5, 6]:
    cycles = generate_cycles(k)
    print(f"Number of {k}-cycles: {len(cycles)}")
    for cycle in cycles:
        edges_in_cycle = []
        for idx in range(k):
            u, v = cycle[idx], cycle[(idx+1)%k]
            if u < v:
                edges_in_cycle.append(edge[(u,v)])
            else:
                edges_in_cycle.append(edge[(v,u)])
        solver.add(z3.Not(z3.And(edges_in_cycle)))

print("Solving...")
result = solver.check()
print(f"Result: {result}")
if result == z3.sat:
    model = solver.model()
    edges_list = []
    for i in range(n):
        for j in range(i+1, n):
            if z3.is_true(model[edge[(i,j)]]):
                edges_list.append((i,j))
    print(f"Number of edges: {len(edges_list)}")
    print(f"Edges: {edges_list}")
    colors = [model[color[i]].as_long() for i in range(n)]
    print(f"Colors: {colors}")
else:
    print("UNSAT")

