n = 16

def has_short_cycle(edges, max_len=6):
    """Check if graph has any cycle of length <= max_len"""
    # Build adjacency
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS from each vertex to find cycles
    for start in range(n):
        # BFS with parent tracking
        visited = {start: 0}  # vertex -> distance from start
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for w in adj[v]:
                if w == parent[v]:
                    continue
                if w in visited:
                    # Found a cycle
                    cycle_len = visited[v] + visited[w] + 1
                    if cycle_len <= max_len:
                        return True, cycle_len
                else:
                    visited[w] = visited[v] + 1
                    parent[w] = v
                    if visited[w] < max_len:
                        queue.append(w)
    return False, None

def is_3_colorable(edges):
    """Check if graph is 3-colorable using backtracking"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for w in adj[v]:
            if colors[w] != -1:
                used.add(colors[w])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0), colors

